              in2 => reset_1,
              out1 => S_R_Flip_Flop_out1
              );

  Deserializer1D_contl_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Deserializer1D_contl_cnt <= to_unsigned(16#000#, 12);
      Deserializer1D_contl_cntGlobal <= to_unsigned(16#000#, 12);
      Deserializer1D_contl_cntInnerRegCtrol <= to_unsigned(16#800#, 12);
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb_1_25_0 = '1' THEN
        Deserializer1D_contl_cnt <= Deserializer1D_contl_cnt_next;
        Deserializer1D_contl_cntGlobal <= Deserializer1D_contl_cntGlobal_next;
        Deserializer1D_contl_cntInnerRegCtrol <= Deserializer1D_contl_cntInnerRegCtrol_next;
      END IF;
    END IF;
  END PROCESS Deserializer1D_contl_process;

  Deserializer1D_contl_output : PROCESS (Deserializer1D_contl_cnt, Deserializer1D_contl_cntGlobal,
       Deserializer1D_contl_cntInnerRegCtrol, validIn)
    VARIABLE out0 : std_logic;
    VARIABLE validOutput : std_logic;
    VARIABLE cntInnerRegCtrol_temp : unsigned(11 DOWNTO 0);
  BEGIN
    cntInnerRegCtrol_temp := Deserializer1D_contl_cntInnerRegCtrol;
    Deserializer1D_contl_cnt_next <= Deserializer1D_contl_cnt;
    Deserializer1D_tapDelayEn <= validIn;
    Deserializer1D_hOutSignalsContl <= '0';
    out0 := '0';
    Deserializer1D_innerRegCtrolEn <= '0';
    validOutput := '0';
    IF (validIn /= '0') AND (Deserializer1D_contl_cnt = to_unsigned(16#7FF#, 12)) THEN 
      validOutput := '1';
    END IF;
    IF validOutput = '1' THEN 
      Deserializer1D_hOutSignalsContl <= '1';
      out0 := '1';
      Deserializer1D_innerRegCtrolEn <= '1';
      cntInnerRegCtrol_temp := Deserializer1D_contl_cntGlobal;
    END IF;
    IF ( NOT out0) = '1' AND (Deserializer1D_contl_cntGlobal = cntInnerRegCtrol_temp) THEN 
      Deserializer1D_innerRegCtrolEn <= '1';
      cntInnerRegCtrol_temp := to_unsigned(16#800#, 12);
    END IF;
    IF validIn /= '0' THEN 
      IF Deserializer1D_contl_cnt = to_unsigned(16#7FF#, 12) THEN 
        Deserializer1D_contl_cnt_next <= to_unsigned(16#000#, 12);
      ELSE 
        Deserializer1D_contl_cnt_next <= Deserializer1D_contl_cnt + to_unsigned(16#001#, 12);
      END IF;
    END IF;
    IF Deserializer1D_contl_cntGlobal = to_unsigned(16#7FF#, 12) THEN 
      Deserializer1D_contl_cntGlobal_next <= to_unsigned(16#000#, 12);
    ELSE 
      Deserializer1D_contl_cntGlobal_next <= Deserializer1D_contl_cntGlobal + to_unsigned(16#001#, 12);
    END IF;
    Deserializer1D_innerRegEn <= out0;
    IF Deserializer1D_contl_cntGlobal = to_unsigned(16#000#, 12) THEN 
      Deserializer1D_outBypassEn <= '1';
    ELSE 
      Deserializer1D_outBypassEn <= '0';
    END IF;
    Deserializer1D_contl_cntInnerRegCtrol_next <= cntInnerRegCtrol_temp;
  END PROCESS Deserializer1D_contl_output;


  Deserializer1D_tapDelayEn_1 <= enb_1_25_0 AND Deserializer1D_tapDelayEn;

  data_signed <= signed(data);

  Deserializer1D_tapDelayComp_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Deserializer1D_tapout <= (OTHERS => to_signed(16#000#, 12));
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb_1_25_0 = '1' AND Deserializer1D_tapDelayEn_1 = '1' THEN
        Deserializer1D_tapout(2046) <= data_signed;
        Deserializer1D_tapout(0 TO 2045) <= Deserializer1D_tapout(1 TO 2046);
      END IF;
    END IF;
  END PROCESS Deserializer1D_tapDelayComp_process;


  data_signed_1 <= signed(data);

  Deserializer1D_muxOut_gen: FOR idx0 IN 0 TO 2046 GENERATE
    Deserializer1D_muxOut(idx0) <= Deserializer1D_tapout(idx0);
  END GENERATE;
  Deserializer1D_muxOut(2047) <= data_signed_1;

  Deserializer1D_innerRegComp_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Deserializer1D_deserInnerOut <= (OTHERS => to_signed(16#000#, 12));
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb_1_25_0 = '1' AND Deserializer1D_innerRegEn = '1' THEN
        Deserializer1D_deserInnerOut <= Deserializer1D_muxOut;
      END IF;
    END IF;
  END PROCESS Deserializer1D_innerRegComp_process;


  Deserializer1D_OutRegComp_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Deserializer1D_OutRegComp_reg <= (OTHERS => to_signed(16#000#, 12));
    ELSIF clk'EVENT AND clk = '1' THEN
      IF Deserializer1D_outBypassEn = '1' AND enb_1_25_0 = '1' THEN
        Deserializer1D_OutRegComp_reg <= Deserializer1D_deserInnerOut;
      END IF;
    END IF;
  END PROCESS Deserializer1D_OutRegComp_process;

  
  deserializer_PostProcessed <= Deserializer1D_deserInnerOut WHEN Deserializer1D_outBypassEn = '1' ELSE
      Deserializer1D_OutRegComp_reg;

  Rate_Transition2_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      deserializer_PostProcessed_1 <= (OTHERS => to_signed(16#000#, 12));
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb_1_51200_0 = '1' THEN
        deserializer_PostProcessed_1 <= deserializer_PostProcessed;
      END IF;
    END IF;
  END PROCESS Rate_Transition2_process;


  Rate_Transition_out1 <= deserializer_PostProcessed_1;

  outputgen: FOR k IN 0 TO 2047 GENERATE
    Rate_Transition_out1_1(k) <= std_logic_vector(Rate_Transition_out1(k));
  END GENERATE;

  Deserializer1D_innerRegComp_1_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Deserializer1D_deserInnerOut_1 <= '0';
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb_1_25_0 = '1' AND Deserializer1D_innerRegCtrolEn = '1' THEN
        Deserializer1D_deserInnerOut_1 <= Deserializer1D_hOutSignalsContl;
      END IF;
    END IF;
  END PROCESS Deserializer1D_innerRegComp_1_process;


  Deserializer1D_OutRegComp_1_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Deserializer1D_OutRegComp_reg_1 <= '0';
    ELSIF clk'EVENT AND clk = '1' THEN
      IF Deserializer1D_outBypassEn = '1' AND enb_1_25_0 = '1' THEN
        Deserializer1D_OutRegComp_reg_1 <= Deserializer1D_deserInnerOut_1;
      END IF;
    END IF;
  END PROCESS Deserializer1D_OutRegComp_1_process;

  
  Deserializer1D_out2 <= Deserializer1D_deserInnerOut_1 WHEN Deserializer1D_outBypassEn = '1' ELSE
      Deserializer1D_OutRegComp_reg_1;

  Rate_Transition11_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Deserializer1D_out2_1 <= '0';
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb_1_51200_0 = '1' THEN
        Deserializer1D_out2_1 <= Deserializer1D_out2;
      END IF;
    END IF;
  END PROCESS Rate_Transition11_process;


  Rate_Transition1_out1 <= Deserializer1D_out2_1;

  Delay_process : PROCESS (clk, reset)
  BEGIN
    IF reset = '1' THEN
      Delay_reg <= (OTHERS => '0');
    ELSIF clk'EVENT AND clk = '1' THEN
      IF enb_1_25_0 = '1' THEN
        IF reset_1 = '1' THEN
